1	import { timestampDate } from "@bufbuild/protobuf/wkt";
2	import { Code, ConnectError, createClient, type Interceptor } from "@connectrpc/connect";
3	import { createConnectTransport } from "@connectrpc/connect-web";
4	import { getAccessToken, hasStoredToken, isTokenExpired, REQUEST_TOKEN_EXPIRY_BUFFER_MS, setAccessToken } from "./auth-state";
5	import { AIService } from "./types/proto/api/v1/ai_service_pb";
6	import { AttachmentService } from "./types/proto/api/v1/attachment_service_pb";
7	import { AuthService } from "./types/proto/api/v1/auth_service_pb";
8	import { IdentityProviderService } from "./types/proto/api/v1/idp_service_pb";
9	import { InstanceService } from "./types/proto/api/v1/instance_service_pb";
10	import { MemoService } from "./types/proto/api/v1/memo_service_pb";
11	import { ShortcutService } from "./types/proto/api/v1/shortcut_service_pb";
12	import { UserService } from "./types/proto/api/v1/user_service_pb";
13	import { redirectOnAuthFailure } from "./utils/auth-redirect";
14	
15	interface RequestWithHeader {
16	  header: Headers;
17	}
18	
19	// ============================================================================
20	// Constants
21	// ============================================================================
22	
23	const RETRY_HEADER = "X-Retry";
24	const RETRY_HEADER_VALUE = "true";
25	
26	// ============================================================================
27	// Token Refresh State Management
28	// ============================================================================
29	
30	const createTokenRefreshManager = () => {
31	  let isRefreshing = false;
32	  let refreshPromise: Promise<void> | null = null;
33	
34	  return {
35	    async refresh(refreshFn: () => Promise<void>): Promise<void> {
36	      if (isRefreshing && refreshPromise) {
37	        return refreshPromise;
38	      }
39	
40	      isRefreshing = true;
41	      refreshPromise = refreshFn().finally(() => {
42	        isRefreshing = false;
43	        refreshPromise = null;
44	      });
45	
46	      return refreshPromise;
47	    },
48	  };
49	};
50	
51	const tokenRefreshManager = createTokenRefreshManager();
52	
53	// ============================================================================
54	// Token Refresh
55	// ============================================================================
56	
57	const fetchWithCredentials: typeof globalThis.fetch = (input, init) => {
58	  return globalThis.fetch(input, {
59	    ...init,
60	    credentials: "include",
61	  });
62	};
63	
64	// Separate transport without auth interceptor to prevent recursion
65	const refreshTransport = createConnectTransport({
66	  baseUrl: window.location.origin,
67	  useBinaryFormat: true,
68	  fetch: fetchWithCredentials,
69	  interceptors: [],
70	});
71	
72	const refreshAuthClient = createClient(AuthService, refreshTransport);
73	
74	async function doRefreshAccessToken(): Promise<void> {
75	  const response = await refreshAuthClient.refreshToken({});
76	
77	  if (!response.accessToken) {
78	    throw new ConnectError("Refresh token response missing access token", Code.Internal);
79	  }
80	
81	  const expiresAt = response.expiresAt ? timestampDate(response.expiresAt) : undefined;
82	  setAccessToken(response.accessToken, expiresAt);
83	}
84	
85	// All callers go through the manager to deduplicate concurrent refresh requests.
86	// This prevents race conditions between useTokenRefreshOnFocus (proactive refresh
87	// on tab focus) and the auth interceptor (reactive refresh on 401), which could
88	// otherwise send duplicate requests that conflict with server-side token rotation.
89	export async function refreshAccessToken(): Promise<void> {
90	  return tokenRefreshManager.refresh(doRefreshAccessToken);
91	}
92	
93	// ============================================================================
94	// Authentication Interceptor Helpers
95	// ============================================================================
96	
97	function setAuthorizationHeader(req: RequestWithHeader, token: string | null) {
98	  if (!token) return;
99	  req.header.set("Authorization", `Bearer ${token}`);
100	}
101	
102	function shouldHandleUnauthenticatedRetry(error: unknown, isRetryAttempt: boolean): boolean {
103	  if (!(error instanceof ConnectError)) {
104	    return false;
105	  }
106	  if (error.code !== Code.Unauthenticated) {
107	    return false;
108	  }
109	  if (isRetryAttempt) {
110	    return false;
111	  }
112	  return true;
113	}
114	
115	async function refreshAndGetAccessToken(): Promise<string> {
116	  await refreshAccessToken();
117	  const token = getAccessToken();
118	  if (!token) {
119	    throw new ConnectError("Token refresh succeeded but no token available", Code.Internal);
120	  }
121	  return token;
122	}
123	
124	export async function getRequestToken(): Promise<string | null> {
125	  let token = getAccessToken();
126	  if (!token) {
127	    if (!hasStoredToken()) return null;
128	    try {
129	      token = await refreshAndGetAccessToken();
130	    } catch {
131	      return null;
132	    }
133	    return token;
134	  }
135	
136	  // Preflight refresh: avoid sending requests with expired access tokens.
137	  // This is especially important for public endpoints (e.g. ListMemos), where
138	  // an expired token could otherwise be treated as anonymous and return
139	  // guest-scoped data before the reactive 401 refresh path runs.
140	  if (isTokenExpired(REQUEST_TOKEN_EXPIRY_BUFFER_MS)) {
141	    try {
142	      token = await refreshAndGetAccessToken();
143	    } catch {
144	      // Keep existing reactive 401 flow as fallback.
145	      // Protected methods still trigger refresh/redirect in the catch block below.
146	    }
147	  }
148	
149	  return token;
150	}
151	
152	// ============================================================================
153	// Authentication Interceptor
154	// ============================================================================
155	
156	const authInterceptor: Interceptor = (next) => async (req) => {
157	  const isRetryAttempt = req.header.get(RETRY_HEADER) === RETRY_HEADER_VALUE;
158	  const token = await getRequestToken();
159	  setAuthorizationHeader(req, token);
160	
161	  try {
162	    return await next(req);
163	  } catch (error) {
164	    if (!shouldHandleUnauthenticatedRetry(error, isRetryAttempt)) {
165	      throw error;
166	    }
167	
168	    try {
169	      const newToken = await refreshAndGetAccessToken();
170	      setAuthorizationHeader(req, newToken);
171	      req.header.set(RETRY_HEADER, RETRY_HEADER_VALUE);
172	      return await next(req);
173	    } catch (refreshError) {
174	      redirectOnAuthFailure();
175	      throw refreshError;
176	    }
177	  }
178	};
179	
180	// ============================================================================
181	// Transport & Service Clients
182	// ============================================================================
183	
184	const transport = createConnectTransport({
185	  baseUrl: window.location.origin,
186	  useBinaryFormat: true,
187	  fetch: fetchWithCredentials,
188	  interceptors: [authInterceptor],
189	});
190	
191	// Core service clients
192	export const instanceServiceClient = createClient(InstanceService, transport);
193	export const authServiceClient = createClient(AuthService, transport);
194	export const userServiceClient = createClient(UserService, transport);
195	
196	// Content service clients
197	export const memoServiceClient = createClient(MemoService, transport);
198	export const attachmentServiceClient = createClient(AttachmentService, transport);
199	export const aiServiceClient = createClient(AIService, transport);
200	export const shortcutServiceClient = createClient(ShortcutService, transport);
201	
202	// Configuration service clients
203	export const identityProviderServiceClient = createClient(IdentityProviderService, transport);
204

